"import os
import re

root_dir = r'D:\veepoo'
cockpit_regex = re.compile(r'cockpit', re.IGNORECASE)

matches = []
for dirpath, dirnames, filenames in os.walk(root_dir):
    # skip .git and virtualenvs/tools if any
    if '.git' in dirpath:
        continue
    for f in filenames:
        ext = os.path.splitext(f)[1].lower()
        if ext in ['.html', '.js', '.css', '.py', '.md', '.txt', '.json']:
            full_path = os.path.join(dirpath, f)
            try:
                with open(full_path, 'r', encoding='utf-8', errors='ignore') as fp:
                    for line_no, line in enumerate(fp, 1):
                        if cockpit_regex.search(line):
                            matches.append((full_path, line_no, line.strip()))
            except Exception as e:
                pass

print(f"Total occurrences of 'cockpit': {len(matches)}")
# Group by file
from collections import defaultdict
by_file = defaultdict(list)
for p, lno, text in matches:
    by_file[p].append((lno, text))

for p, lines in by_file.items():
    print(f"\nFile: {p} ({len(lines)} occurrences)")
    for lno, text in lines[:5]:
        print(f"  Line {lno}: {text[:100]}")
